nextflow_process {

    name "Test Process SAMTOOLS_COLLATEFASTQ"
    script "../main.nf"
    process "SAMTOOLS_COLLATEFASTQ"

    tag "modules"
    tag "modules_nfcore"
    tag "samtools"
    tag "samtools/collatefastq"

    test("human - bam - paired_end") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true)
                ]
                input[1] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true),
                    []
                ]
                input[2] = false
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                    process.out.fastq,
                    process.out.findAll { key, val -> key.startsWith("versions") }
                ).match() }
            )
        }
    }

    test("human - bam - single_end") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:true ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.single_end.bam', checkIfExists: true)
                ]
                input[1] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true),
                    []
                ]
                input[2] = false
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                    process.out.fastq_other,
                    process.out.findAll { key, val -> key.startsWith("versions") }
                ).match() }
            )
        }
    }

